  (* [comment removed for export] *)
  Lemma flm : forall x, In x l -> exists mtx, a_meta A x = Some mtx /\ mt_role mtx = RFree /\
    0x1000 <= x /\ x + 40 <= alloc_ceiling /\ (forall j, 0 <= j < 40 -> dom A (x + j)) /\
